import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·11","description":"易小帖 - 卷五·11","frontmatter":{"title":"卷五·11","description":"易小帖 - 卷五·11"},"headers":[],"relativePath":"classics/yixiaotie/133.md","filePath":"classics/yixiaotie/133.md"}'),o={name:"classics/yixiaotie/133.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·11",tabindex:"-1"},[r("卷五·11 "),e("a",{class:"header-anchor",href:"#卷五·11","aria-label":"Permalink to “卷五·11”"},"​")],-1),e("p",null,"塨啟塨讀先生易傳，已廓然大闢一天地矣。第系傳一條，尚有請者。易有太極節，先儒舊說，原不解，以兩儀為天地，則八卦之乾坤即天地也，豈天地生天地乎。繫辭曰：天地設位而易行乎其中，是易者從乾坤六子而名之者也。所謂有天地然後有易也。今乃言易有太極，以生天地，豈有易然後有天地乎。先生直以太極為乾，兩儀為乾坤合一，而後從兩乾兩坤分四象，以生八卦，其首末一串，相生無礙。真度越前儒遠矣。今塨細讀易傳，至先生解夫易何為句，謂是闡大衍五十之數，怳然有省，因生一妄解，敢請教。正太極者，大衍之捨一不用者也（崔憬有此說），兩儀者分而為二以象兩也，四象者揲之以四以象四時也，八卦則四揲十有八變而成之者也。言易大衍之數，遞生以成八卦，而吉凶以定，趨吉避兇，而大業以生，仍闡明揲蓍之故也。其不言掛一歸奇者，即在兩四之內也。觀前有興神物以前民用，後有定吉凶莫大乎蓍龜，及易有四象，定之以吉凶諸語，似申言大衍之數以為揲蓍致意者。惟先生教之。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
